from pathlib import Path
import base64
root=Path(__file__).parent
uri=lambda f,m:'data:'+m+';base64,'+base64.b64encode((root/'assets'/f).read_bytes()).decode()
hero=uri('hero.jpg','image/jpeg');park=uri('park.jpg','image/jpeg');plan=uri('plan.png','image/png')
P=[]
def page(body,n,cls='',hard=False):
 running=f'<div class="running"><span>Gamuda Central Park</span><span>The living journal</span></div>'
 folio=f'<div class="folio"><span>CONCEPT EDITION</span><span>{n:02}</span></div>'
 P.append(f'<section class="sheet {cls}" data-density="{"hard" if hard else "soft"}" aria-label="Trang {n}"><div class="inner">{running if 0<n<11 else ""}{body}{folio if 0<n<11 else ""}</div></section>')
page(f'<div class="running"><span>The living journal</span><span>Vol. 01</span></div><h1>Gamuda<br>Central<br><em>Park.</em></h1><p class="subtitle">Một khoảng thở.<br>Một chương sống mới.</p><img class="coverphoto" src="{hero}" alt="Phối cảnh tham khảo gồm ba tòa dự án"><div class="edition"><span>HÀNH TRÌNH CHỌN TỔ ẤM</span><span>DESIGN CONCEPT</span></div>',0,'cover',True)
page('<div class="eyebrow">Lời ngỏ</div><h2>Những điều<br>làm nên<br><em>một mái nhà.</em></h2><p class="lede">Có những lựa chọn cần nhiều hơn một bảng thông số.</p><p class="drop">Một nơi ở bắt đầu từ cảm giác: buổi sáng thức dậy, một góc nhìn qua cửa sổ, và khoảng thời gian cả nhà được ở bên nhau.</p><p>Cuốn tạp chí này là lời mời anh chị chậm lại một chút, xem kỹ hơn và cùng tìm một không gian phù hợp với cuộc sống của mình.</p><div class="quote">“Nhà là nơi<br>mình muốn trở về.”</div>',1)
page('<div class="eyebrow">Trong số này</div><h2>Mở từng trang.<br><em>Hiểu từng điều.</em></h2>'+''.join(f'<button class="tocrow" data-jump="{n}">{t}<span>{n:02}</span></button>' for t,n in [('Khoảng thở của cuộc sống',3),('Tổng thể & cảnh quan',5),('Mặt bằng & lựa chọn',7),('Sở hữu & kết nối',9)])+'<p class="small" style="margin-top:9%">Kéo chậm góc dưới của trang sang phía đối diện. Có thể dừng giữa chừng và thả tay để trang giấy trở về.</p>',2)
page('<div class="eyebrow">01 / Cảm hứng sống</div><div class="display-number">01</div><h2>Để thiên nhiên<br>có chỗ trong<br><em>mỗi ngày.</em></h2><p class="lede">Một khoảng xanh trong tầm mắt.<br>Một nhịp sống có khoảng nghỉ.</p><p class="small">Bắt đầu hành trình lựa chọn căn hộ từ những điều gia đình trân trọng: không gian sống, sự kết nối và thời gian dành cho nhau.</p>',3,'dark')
page(f'<img src="{park}" alt="Phối cảnh cảnh quan tham khảo"><div class="overlay"><div class="eyebrow">Không gian & cảm xúc</div><h2>Chậm lại.<br><em>Để tận hưởng.</em></h2><p class="small" style="color:#eee9d6">Phối cảnh tham khảo từ trang giới thiệu dự án.<br>Danh mục tiện ích cần đối chiếu tài liệu được duyệt.</p><div class="folio"><span>THE LIVING JOURNAL</span><span>04</span></div></div>',4,'bleed')
# remove running/folio for the full-bleed page
P[-1]=P[-1].replace('<div class="running"><span>Gamuda Central Park</span><span>The living journal</span></div>','').replace('<div class="folio"><span>CONCEPT EDITION</span><span>04</span></div>','')
page(f'<div class="eyebrow">02 / Góc nhìn tổng thể</div><h2>Một tổng thể.<br><em>Nhiều góc nhìn.</em></h2><img class="photo wide" src="{hero}" alt="Toàn cảnh ba tòa trong hình tham khảo"><p class="caption">PHỐI CẢNH THAM KHẢO · NGUỒN: GAMUDACITYHANOI.COM</p><div class="cols"><p>Quan sát tổng thể giúp hình dung mối quan hệ giữa các khối nhà, khoảng xanh và không gian xung quanh.</p><p>Khi chọn căn cụ thể, cần đối chiếu hướng, vị trí và tầm nhìn trên hồ sơ đúng tòa, đúng tầng.</p></div>',5)
page('<div class="eyebrow">Chọn nơi sống</div><h2>Đẹp trong mắt.<br><em>Hợp trong<br>cuộc sống.</em></h2><div class="details"><div class="detail"><b>01 / Hành trình mỗi ngày</b><p>Đi làm, đi học và các điểm sinh hoạt quen thuộc của gia đình kết nối ra sao?</p></div><div class="detail"><b>02 / Không gian thật sự cần</b><p>Số phòng, khu sinh hoạt chung và khả năng sử dụng lâu dài có phù hợp?</p></div><div class="detail"><b>03 / Điều cần kiểm chứng</b><p>Pháp lý, tiến độ, tiêu chuẩn bàn giao và tiện ích được thể hiện thế nào trong tài liệu chính thức?</p></div></div>',6)
page('<div class="eyebrow">03 / Nghệ thuật chọn căn</div><div class="display-number">03</div><h2>Đọc mặt bằng.<br><em>Hình dung<br>cuộc sống.</em></h2><p class="lede">Một bản vẽ sẽ có ý nghĩa hơn khi đặt vào nhu cầu của chính mình.</p><p>Hãy bắt đầu từ cách gia đình sinh hoạt, vị trí các phòng và những khoảng không gian được sử dụng nhiều nhất.</p><p class="small">Mặt bằng ở trang bên là ảnh tham khảo có nguồn. Chưa xác minh tòa, tầng và phiên bản áp dụng; không dùng để xác nhận thông số căn hộ.</p>',7)
page(f'<div class="eyebrow">Bản vẽ / Xem chi tiết</div><h2>Từ đường nét<br><em>đến tổ ấm.</em></h2><img class="plan" src="{plan}" alt="Mặt bằng tầng tham khảo, chưa xác minh phiên bản"><p class="caption">MẶT BẰNG THAM KHẢO · CẦN ĐỐI CHIẾU PHIÊN BẢN</p><button class="page-button" data-zoom>Phóng lớn mặt bằng ↗</button><p class="small" style="margin-top:7%">Xem ảnh lớn để quan sát bố trí. Thông số giao dịch phải căn cứ hồ sơ chính thức của căn được chọn.</p>',8)
page('<div class="eyebrow">04 / Quyết định sở hữu</div><h2>Đúng cảm xúc.<br><em>Rõ thông tin.</em></h2><div class="details"><div class="detail"><b>Giá & tổng chi phí</b><p>Đối chiếu giá căn, thuế, phí và các khoản chưa bao gồm.</p></div><div class="detail"><b>Lịch thanh toán & phương án vay</b><p>Làm rõ từng mốc thanh toán, điều kiện ưu đãi và nghĩa vụ sau ưu đãi.</p></div><div class="detail"><b>Hồ sơ & điều kiện áp dụng</b><p>Kiểm tra văn bản, thời hạn áp dụng và thông tin của đúng căn hộ.</p></div></div><p class="small">Giá và chính sách sẽ được bổ sung từ văn bản mới nhất đã được phê duyệt.</p>',9)
page('<div class="eyebrow">Hẹn một cuộc trò chuyện</div><h2>Chương tiếp theo,<br><em>viết cùng<br>anh chị.</em></h2><p class="lede">Cùng xem mặt bằng.<br>Cùng tìm lựa chọn phù hợp.</p><div class="masthead">Let’s find<br><em>your place.</em></div><p class="agent-name">Chuyên viên đồng hành.</p><a class="agent-phone">Thêm thông tin liên hệ</a><button class="page-button" data-sale style="margin-top:6%">Thông tin chuyên viên</button>',10)
page('<div class="eyebrow">THE LIVING JOURNAL</div><h1 style="margin-top:8%">Gamuda<br>Central<br><em>Park.</em></h1><p class="subtitle" style="margin-top:8%">Khép một cuốn tạp chí.<br>Mở một câu chuyện mới.</p><div style="width:15%;height:1px;background:#b3a27d;margin:12% 0"></div><p class="small" style="color:#c6cfb9">Bản mẫu thiết kế & trải nghiệm.<br>Chưa phải tài liệu công bố của chủ đầu tư.</p><div class="edition"><span>CONCEPT EDITION</span><span>VOL. 01</span></div>',11,'cover',True)
s=(root/'template.html').read_text().replace('<!--PAGES-->','\n'.join(P)).replace('@@PLAN@@',plan).replace('@@LIBRARY@@',(root/'node_modules/page-flip/dist/js/page-flip.browser.js').read_text())
(root/'index.html').write_text(s)
(root.parent/'Gamuda-Central-Park-Magazine-v3.html').write_text(s)
print('Built',len(s),'characters,',len(P),'pages')
